fun encrypt(plain: ByteArray, key: SecretKey): ByteArray {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, key)
    val iv = cipher.iv
    return iv + cipher.doFinal(plain)   // store iv + ciphertext together
}

fun decrypt(data: ByteArray, key: SecretKey): ByteArray {
    val iv = data.copyOfRange(0, 12)
    val ciphertext = data.copyOfRange(12, data.size)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, iv))
    return cipher.doFinal(ciphertext)
}

private const val PKCE_ALPHABET =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"

fun pkcePair(): Pair<String, String> {
    val verifier = (1..64).map { PKCE_ALPHABET.random() }.joinToString("")
    val digest = MessageDigest.getInstance("SHA-256").digest(verifier.toByteArray())
    val challenge = Base64.getUrlEncoder().withoutPadding().encodeToString(digest)
    return verifier to challenge
}

