enum class Severity { INFO, WARN, CRITICAL }

data class Finding(val control: String, val severity: Severity, val detail: String)

fun scanMergedManifest(manifestText: String): List<Finding> = buildList {
    if ("cleartextTrafficPermitted=\"true\"" in manifestText)
        add(Finding("MASVS-NETWORK-1", Severity.CRITICAL, "cleartext traffic permitted"))
    if ("android:allowBackup=\"true\"" in manifestText)
        add(Finding("MASVS-DATA-2", Severity.WARN, "backup may expose data"))
    if ("android:exported=\"true\"" in manifestText)
        add(Finding("MASVS-PLATFORM-1", Severity.WARN, "exported component found"))
}

