fun gateAccess(
    attestation: IntegrityResult,
    profile: WorkProfileState
): AccessDecision {
    val verified = attestation.isVerified && !attestation.isDeviceTampered
    val compliant = profile.isPolicyCompliant && profile.isLockedAtBoot
    return when {
        verified && compliant -> AccessDecision.FULL
        verified             -> AccessDecision.READ_ONLY
        else                 -> AccessDecision.DENIED
    }
}
